import sys,json,shutil,difflib
from pathlib import Path
B=Path('.dedup-work/immich12-20261021');sys.path.insert(0,str((B/'review-deps').resolve()));import sass,tinycss2
S=B/'scss-review';S.mkdir(exist_ok=True)
for f in B.glob('src--scss--*.scss'):shutil.copyfile(f,S/f.name.removeprefix('src--scss--'))
def canonical(tokens):
 result=[]
 for t in tokens:
  if t.type in ['whitespace','comment']:continue
  if t.type=='error':raise ValueError(str(t))
  if t.type in ['at-rule','qualified-rule']:
   result.append([t.type,getattr(t,'at_keyword',None),canonical(t.prelude),canonical(t.content or [])])
  elif hasattr(t,'content'):result.append([t.type,canonical(t.content)])
  elif hasattr(t,'arguments'):result.append([t.type,t.name,canonical(t.arguments)])
  else:result.append([t.type,getattr(t,'value',None),getattr(t,'unit',None)])
 return result
out={}
for name in ['base','bs5','comp','main.base','main']:
 compiled=sass.compile(filename=str(S/(name+'.scss')),output_style='compact');original=(B/('src--assets--'+name+'.css')).read_text();a=canonical(tinycss2.parse_stylesheet(original));b=canonical(tinycss2.parse_stylesheet(compiled));out[name]={'original_rules':len(a),'compiled_rules':len(b),'same_token_tree':a==b,'byte_identical':original==compiled}
 if a!=b:
  out[name]['first_differences']=list(difflib.unified_diff(json.dumps(a,indent=1).splitlines(),json.dumps(b,indent=1).splitlines()))[:100]
(B/'style-compare-v17-result.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
